css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); display: grid; place-items: center; }
.loader span { width: 26%; height: 80%; background: var(--accent); border-radius: calc(var(--loader-size) * .05); position: relative; box-shadow: 0 0 calc(var(--loader-size) * .16) color-mix(in srgb, var(--accent-2) 65%, transparent); animation: cross calc(var(--loader-speed) * 1.6) ease-in-out infinite; }
.loader span::after { content: ''; position: absolute; top: 37%; left: -100%; width: 300%; height: 26%; background: inherit; border-radius: inherit; }
@keyframes cross { 0%, 100% { transform: scale(.7) rotate(0deg); } 50% { transform: scale(1) rotate(90deg); } }
